// Gate + validate. REAL: response must be a REAL vendor communication (email/vendor_api/vendor_portal) with price+currency+timestamp+evidence. DEMO: explicitly labeled human input (mode=DEMO, channel=demo, DEMO_HUMAN_ENTERED) with verified identities + explicit price; REAL validation untouched.
const i = $input.first().json;
if (!i.procurement_id) throw new Error('Missing procurement_id');
if (!i.negotiation) return [{ json: { procurement_id: i.procurement_id, status: 'NOT_ELIGIBLE', reason: 'no negotiation exists', negotiation_id: null } }];
const demo = i.mode === 'DEMO' && i.vendor_response?.channel === 'demo' && i.vendor_response?.response_mode === 'DEMO_HUMAN_ENTERED';
if (demo) {
  const r = i.vendor_response, bad = [];
  if (!i.offer?.offer_id) bad.push('offer identity unverifiable');
  if (!i.vendor?.vendor_id || !i.vendor?.vendor_name || i.vendor.vendor_name === 'unavailable') bad.push('vendor identity unverifiable');
  if (!i.product?.product_id) bad.push('product identity unverifiable');
  if (!(typeof r.revised_price === 'number' && r.revised_price > 0)) bad.push('demo revised price must be explicitly entered (> 0)');
  if (!r.currency) bad.push('demo currency missing');
  if (i.offer?.currency && String(r.currency).toUpperCase() !== String(i.offer.currency).toUpperCase()) bad.push('demo currency must match offer (no conversion)');
  if (bad.length) throw new Error('demo response rejected: ' + bad.join('; '));
  return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, mode: 'DEMO', negotiation: i.negotiation, offer: i.offer, vendor: i.vendor, product: i.product, vendor_response: { ...r, currency: String(r.currency).toUpperCase(), received_at: r.received_at ?? new Date().toISOString(), source: 'LOCAL_DEMO_INPUT', vendor_response_verified: false }, original: i.original, weights: i.weights } }];
}
if (i.vendor_response?.channel === 'demo') throw new Error('demo response in REAL mode');
if (!i.vendor_response || typeof i.vendor_response !== 'object' || !(typeof i.vendor_response.revised_price === 'number')) return [{ json: { procurement_id: i.procurement_id, negotiation_id: i.negotiation.negotiation_id ?? null, status: 'WAITING_FOR_VENDOR', reason: 'no verified vendor response' } }];
const r = i.vendor_response, bad = [];
if (!i.offer?.offer_id) bad.push('offer identity unverifiable');
if (!i.vendor?.vendor_id || !i.vendor?.vendor_name || i.vendor.vendor_name === 'unavailable') bad.push('vendor identity unverifiable');
if (!i.product?.product_id) bad.push('product identity unverifiable');
if (r.vendor_id && r.vendor_id !== i.vendor.vendor_id) bad.push('response vendor mismatch');
if (r.offer_id && r.offer_id !== i.offer.offer_id) bad.push('response offer mismatch');
if (!(typeof r.revised_price === 'number' && r.revised_price > 0)) bad.push('malformed revised price');
if (!r.currency) bad.push('revised currency missing');
if (!r.received_at) bad.push('response timestamp missing');
if (!r.source || !r.source_url) bad.push('evidence source missing');
if (!['email','vendor_api','vendor_portal'].includes(r.channel)) bad.push('untraceable response channel');
if (bad.length) throw new Error('vendor response rejected: ' + bad.join('; '));
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, mode: 'REAL', negotiation: i.negotiation, offer: i.offer, vendor: i.vendor, product: i.product, vendor_response: r, original: i.original, weights: i.weights } }];

// Pass ORIGINAL components to the scoring engine (first of two reuse calls).
const i = $input.first().json;
return [{ json: { components: i.original.components ?? {}, weights: i.weights ?? {} } }];

// Build REVISED components: only price-driven criteria may change (budget_compliance from verified revised price, same currency only).
const orig = $('Original Components').first().json;
const gated = $('Gate & Validate').first().json;
const r = gated.vendor_response, o = gated.original;
const comps = { ...(orig.components || {}) };
const ccyOk = r.currency && o.currency && String(r.currency).toUpperCase() === String(o.currency).toUpperCase();
if (typeof r.revised_price === 'number' && ccyOk && typeof o.budget === 'number' && o.budget > 0) comps.budget_compliance = r.revised_price <= o.budget ? 1 : 0;
else if (!ccyOk) comps.budget_compliance = null;
return [{ json: { components: comps, weights: orig.weights ?? {} } }];

// Assemble output: deltas + savings (two real same-currency prices only) + changed criteria.
const before = $('Score Original').first().json;
const after = $input.first().json;
const gated = $('Gate & Validate').first().json;
const r = gated.vendor_response, o = gated.original;
const changed = Object.keys(after.breakdown || {}).filter((k) => JSON.stringify((before.breakdown || {})[k]) !== JSON.stringify(after.breakdown[k]));
const ccyOk = r.currency && o.currency && String(r.currency).toUpperCase() === String(o.currency).toUpperCase();
const op = (typeof o.price === 'number' && o.price > 0) ? o.price : null;
const rp = (typeof r.revised_price === 'number' && r.revised_price > 0) ? r.revised_price : null;
const sav = (op !== null && rp !== null && ccyOk) ? { a: Math.round((op - rp) * 100) / 100, p: Math.round((op - rp) / op * 10000) / 100 } : { a: 'unavailable', p: 'unavailable' };
const delta = (before.overall_score === null || after.overall_score === null) ? null : Math.round((after.overall_score - before.overall_score) * 10000) / 10000;
const ev = [r.source_url].concat(gated.product?.evidence_urls ?? []).filter(Boolean);
return [{ json: { procurement_id: gated.procurement_id, negotiation_id: gated.negotiation.negotiation_id, product_id: gated.product.product_id, vendor_id: gated.vendor.vendor_id, offer_id: gated.offer.offer_id, original_score: before.overall_score ?? null, revised_score: after.overall_score ?? null, score_delta: delta, original_price: op !== null ? op : 'unavailable', revised_price: rp !== null ? rp : 'unavailable', currency: o.currency ?? r.currency ?? null, absolute_savings: sav.a, percentage_savings: sav.p, criteria_changed: changed, criteria_used: after.criteria_used ?? [], criteria_missing: after.criteria_missing ?? [], evidence_urls: [...new Set(ev)], status: 'REEVALUATED', mode: gated.mode ?? 'REAL', response_mode: gated.mode === 'DEMO' ? 'DEMO_HUMAN_ENTERED' : undefined, created_at: new Date().toISOString() } }];
